/* oxlint-disable typescript/unbound-method */
import type { HevyClient } from "@hevy-mcp/hevy-client";
import { Effect } from "effect";
import { z } from "zod";
import {
	createMockHevyClient,
	createMockMcpServer,
} from "../../test-fixtures/mock-hevy.js";
import {
	routinesGetDescriptor,
	routinesListDescriptor,
	type HevyOperations,
	workoutsGetDescriptor,
	workoutsListDescriptor,
} from "@hevy-mcp/operations";
import type { ToolExecutionContext } from "../execution.js";
import { describe, expect, it, vi } from "vitest";
import { createToolRuntime } from "./tool-runtime.js";
import { registerToolDefinition } from "./define-tool.js";
import { workoutToolDefinitions } from "./workouts.js";
import { workoutInputSchema } from "./input-schemas.js";
import { HevyOperationsService } from "../effect-services.js";
type WorkoutToolArgs = Parameters<
	(typeof workoutToolDefinitions)[number]["execute"]
>[1];

function register(
	client: HevyClient | null,
	operations?: HevyOperations,
	execution?: ToolExecutionContext,
) {
	const { server, registerTool: tool } = createMockMcpServer();
	const runtime = createToolRuntime({
		client,
		operations,
		execution,
		catalog: {} as never,
	});
	for (const definition of workoutToolDefinitions) {
		registerToolDefinition(server, runtime, definition);
	}
	return tool;
}

function registerRuntime(runtime: ReturnType<typeof createToolRuntime>) {
	const { server, registerTool: tool } = createMockMcpServer();
	for (const definition of workoutToolDefinitions) {
		registerToolDefinition(server, runtime, definition);
	}
	return tool;
}

function toolHandler(tool: ReturnType<typeof vi.fn>, name: string) {
	const call = tool.mock.calls.find(
		([registeredName]) => registeredName === name,
	);
	if (!call) throw new Error(`Tool ${name} was not registered`);
	return call.at(-1) as <TArgs extends WorkoutToolArgs>(
		args: TArgs,
	) => Promise<object>;
}

const workoutInput = workoutInputSchema.parse({
	workout: {
		title: "Push",
		start_time: "2025-01-01T10:00:00Z",
		end_time: "2025-01-01T11:00:00Z",
		exercises: [
			{ exercise_template_id: "bench", sets: [{ type: "normal", reps: 8 }] },
		],
	},
});

describe("workout tools", () => {
	it("exposes only generated-aligned snake_case input keys", () => {
		const tool = register(null);
		const registration = tool.mock.calls.find(
			([name]) => name === "get-workouts",
		);
		if (!registration) throw new Error("Tool was not registered");
		const inputSchema = registration[1]?.inputSchema;
		if (!inputSchema) throw new Error("Tool input schema is missing");
		const parsedInputSchema = z.instanceof(z.ZodType).parse(inputSchema);

		expect(parsedInputSchema.parse({ page: 2, page_size: 5 })).toEqual({
			page: 2,
			page_size: 5,
		});
		expect(() => parsedInputSchema.parse({ page: 2, pageSize: 5 })).toThrow();
	});

	it("maps snake_case pagination and identifiers to generated client arguments", async () => {
		const client = createMockHevyClient();
		client.getWorkouts.mockResolvedValue({ workouts: [], page_count: 2 });
		client.getWorkout.mockResolvedValue({
			id: "w1",
			start_time: "2025-01-01T10:00:00Z",
			end_time: "2025-01-01T10:30:00Z",
		});
		client.getWorkoutEvents.mockResolvedValue({ events: [], page_count: 1 });
		const tool = register(client);

		await toolHandler(tool, "get-workouts")({ page: 2, page_size: 5 });
		await toolHandler(tool, "get-workout")({ workout_id: "w1" });
		await toolHandler(
			tool,
			"get-workout-events",
		)({ page: 1, page_size: 5, since: "2025-01-01T00:00:00Z" });

		expect(client.getWorkouts).toHaveBeenCalledWith({ page: 2, pageSize: 5 });
		expect(client.getWorkout).toHaveBeenCalledWith("w1");
		expect(client.getWorkoutEvents).toHaveBeenCalledWith({
			page: 1,
			pageSize: 5,
			since: "2025-01-01T00:00:00Z",
		});
	});

	it("uses the injected workout get operation and execution context", async () => {
		const workoutsGetEffect = vi.fn(() =>
			Effect.succeed({
				workout: { id: "w1", title: "Push" },
			}),
		);
		const workoutsListEffect = vi.fn(() =>
			Effect.succeed({
				items: [],
				page: 1,
				pageCount: 1,
			}),
		);
		const routinesGetEffect = vi.fn(() => Effect.succeed({ routine: null }));
		const routinesListEffect = vi.fn(() =>
			Effect.succeed({
				items: [],
				page: 1,
				pageCount: 1,
			}),
		);
		const operations: HevyOperations = {
			workouts: {
				get: {
					descriptor: workoutsGetDescriptor,
					effect: workoutsGetEffect,
					execute: vi.fn(),
				},
				list: {
					descriptor: workoutsListDescriptor,
					effect: workoutsListEffect,
					execute: vi.fn(),
				},
			},
			routines: {
				get: {
					descriptor: routinesGetDescriptor,
					effect: routinesGetEffect,
					execute: vi.fn(),
				},
				list: {
					descriptor: routinesListDescriptor,
					effect: routinesListEffect,
					execute: vi.fn(),
				},
			},
		};
		const execution: ToolExecutionContext = {
			signal: new AbortController().signal,
			deadline: Date.now() + 5_000,
		};
		const tool = register(null, operations, execution);

		const response = await toolHandler(
			tool,
			"get-workout",
		)({
			workout_id: "w1",
		});

		expect(workoutsGetEffect).toHaveBeenCalledWith(
			{ workoutId: "w1" },
			execution,
		);
		expect(response).toMatchObject({
			structuredContent: {
				workout: { id: "w1", title: "Push" },
			},
		});
		expect(response).toMatchObject({ content: [{ type: "text" }] });
	});

	it("resolves both read operations from the service layer, not the getter", async () => {
		const layerWorkoutsGet = vi.fn(() =>
			Effect.succeed({
				workout: { id: "layer-workout", title: "Layer workout" },
			}),
		);
		const layerWorkoutsList = vi.fn(() =>
			Effect.succeed({
				items: [],
				page: 1,
				pageCount: 1,
			}),
		);
		const layerOperations: HevyOperations = {
			workouts: {
				get: {
					descriptor: workoutsGetDescriptor,
					effect: layerWorkoutsGet,
					execute: vi.fn(),
				},
				list: {
					descriptor: workoutsListDescriptor,
					effect: layerWorkoutsList,
					execute: vi.fn(),
				},
			},
			routines: {
				get: {
					descriptor: routinesGetDescriptor,
					effect: vi.fn(),
					execute: vi.fn(),
				},
				list: {
					descriptor: routinesListDescriptor,
					effect: vi.fn(),
					execute: vi.fn(),
				},
			},
		};
		const getterOperations: HevyOperations = {
			...layerOperations,
			workouts: {
				get: {
					...layerOperations.workouts.get,
					effect: vi.fn(() => Effect.fail(new Error("wrong source"))),
				},
				list: {
					...layerOperations.workouts.list,
					effect: vi.fn(() => Effect.fail(new Error("wrong source"))),
				},
			},
		};
		const runtime = createToolRuntime({
			client: createMockHevyClient(),
			operations: layerOperations,
			catalog: {} as never,
		});
		const getOperations = vi
			.spyOn(runtime, "getOperations")
			.mockReturnValue(getterOperations);
		expect(runtime.service(HevyOperationsService)).toBe(layerOperations);
		const tool = registerRuntime(runtime);

		await toolHandler(tool, "get-workouts")({ page: 1, page_size: 5 });
		await toolHandler(tool, "get-workout")({ workout_id: "layer-workout" });

		expect(layerWorkoutsList).toHaveBeenCalledWith(
			{ page: 1, pageSize: 5 },
			undefined,
		);
		expect(layerWorkoutsGet).toHaveBeenCalledWith(
			{ workoutId: "layer-workout" },
			undefined,
		);
		expect(getOperations).not.toHaveBeenCalled();
	});

	it("gets before patching metadata and sends the exact built payload", async () => {
		const calls: string[] = [];
		const current = {
			id: "w1",
			title: "Original",
			description: "Keep",
			start_time: "2025-01-01T10:00:00Z",
			end_time: "2025-01-01T11:00:00Z",
			exercises: [
				{
					index: 0,
					title: "Bench Press",
					exercise_template_id: "bench",
					supersets_id: 4,
					sets: [
						{
							index: 0,
							type: "normal",
							weight_kg: 50,
							reps: 8,
							distance_meters: null,
							duration_seconds: null,
							rpe: null,
							custom_metric: null,
						},
					],
				},
			],
		};
		const client = createMockHevyClient();
		client.createWorkout.mockResolvedValue({
			id: "w1",
			...workoutInput.workout,
		});
		client.getWorkout.mockImplementation(() => {
			calls.push("get");
			return Promise.resolve(current);
		});
		client.updateWorkout.mockImplementation(() => {
			calls.push("put");
			return Promise.resolve(current);
		});
		const tool = register(client);

		await toolHandler(tool, "create-workout")(workoutInput);
		const response = await toolHandler(
			tool,
			"update-workout",
		)({
			workout_id: "w1",
			workout: { title: "Renamed", description: null, is_private: false },
		});

		expect(response).not.toMatchObject({ isError: true });
		expect(calls).toEqual(["get", "put"]);
		expect(client.updateWorkout).toHaveBeenCalledWith("w1", {
			workout: {
				title: "Renamed",
				description: null,
				start_time: "2025-01-01T10:00:00Z",
				end_time: "2025-01-01T11:00:00Z",
				is_private: false,
				exercises: [
					{
						exercise_template_id: "bench",
						superset_id: 4,
						notes: null,
						sets: [
							{
								type: "normal",
								weight_kg: 50,
								reps: 8,
								distance_meters: null,
								duration_seconds: null,
								rpe: null,
								custom_metric: null,
							},
						],
					},
				],
			},
		});
		expect(response).toMatchObject({ content: [{ type: "text" }] });
	});

	it("gets before replacing exercises and preserves metadata", async () => {
		const current = {
			id: "w1",
			title: "Original",
			description: "Keep",
			start_time: "2025-01-01T10:00:00Z",
			end_time: "2025-01-01T11:00:00Z",
			exercises: [
				{
					exercise_template_id: "bench",
					sets: [{ type: "normal", reps: 8 }],
				},
			],
		};
		const client = createMockHevyClient();
		client.getWorkout.mockResolvedValue(current);
		client.updateWorkout.mockResolvedValue(current);
		const tool = register(client);

		await toolHandler(
			tool,
			"replace-workout-exercises",
		)({
			workout_id: "w1",
			workout: {
				is_private: false,
				exercises: [
					{
						exercise_template_id: "row",
						sets: [{ type: "failure", reps: 5 }],
					},
				],
			},
		});

		expect(client.getWorkout).toHaveBeenCalledWith("w1");
		expect(client.updateWorkout).toHaveBeenCalledWith("w1", {
			workout: {
				title: "Original",
				description: "Keep",
				start_time: "2025-01-01T10:00:00Z",
				end_time: "2025-01-01T11:00:00Z",
				is_private: false,
				exercises: [
					{
						exercise_template_id: "row",
						sets: [{ type: "failure", reps: 5 }],
					},
				],
			},
		});
	});
	it("requires is_private when updating workout metadata", () => {
		const client = createMockHevyClient();
		client.getWorkout.mockResolvedValue({
			title: "Original",
			description: "Keep",
			start_time: "2025-01-01T10:00:00Z",
			end_time: "2025-01-01T11:00:00Z",
			exercises: [],
		});
		const tool = register(client);

		expect(() =>
			toolHandler(
				tool,
				"update-workout",
			)({
				workout_id: "w1",
				workout: { description: "Updated" },
			}),
		).toThrow("Invalid input");
		expect(client.getWorkout).not.toHaveBeenCalled();
		expect(client.updateWorkout).not.toHaveBeenCalled();
	});
	it("does not put when GET fails", async () => {
		const getFailureClient = createMockHevyClient();
		getFailureClient.getWorkout.mockRejectedValue(new Error("GET failed"));
		const getFailureTool = register(getFailureClient);
		const getFailure = await toolHandler(
			getFailureTool,
			"update-workout",
		)({
			workout_id: "w1",
			workout: { title: "Renamed", is_private: false },
		});
		expect(getFailure).toMatchObject({ isError: true });
		expect(getFailureClient.updateWorkout).not.toHaveBeenCalled();
	});

	it("reports PUT failures after exactly one GET", async () => {
		const client = createMockHevyClient();
		client.getWorkout.mockResolvedValue({
			title: "Original",
			start_time: "2025-01-01T10:00:00Z",
			end_time: "2025-01-01T11:00:00Z",
			exercises: [],
		});
		client.updateWorkout.mockRejectedValue(new Error("PUT failed"));
		const tool = register(client);

		const response = await toolHandler(
			tool,
			"update-workout",
		)({
			workout_id: "w1",
			workout: { title: "Renamed", is_private: false },
		});

		expect(response).toMatchObject({ isError: true });
		expect(client.getWorkout).toHaveBeenCalledTimes(1);
		expect(client.updateWorkout).toHaveBeenCalledTimes(1);
	});
});

/* oxlint-disable typescript/unbound-method */
import type { JSONObject } from "@modelcontextprotocol/server";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import {
	createMockHevyClient,
	createMockMcpServer,
} from "../../test-fixtures/mock-hevy.js";
import {
	routinesGetDescriptor,
	routinesListDescriptor,
	workoutsGetDescriptor,
	workoutsListDescriptor,
	type HevyOperations,
} from "@hevy-mcp/operations";
import type { ToolExecutionContext } from "../execution.js";
import type { McpToolResponse } from "../utils/response-contracts.js";
import { HevyHttpError } from "@hevy-mcp/hevy-client";
import { Effect } from "effect";
import { describe, expect, it, vi } from "vitest";
import { z } from "zod";
import { getResultTelemetry } from "../utils/result-telemetry.js";
import { createToolRuntime } from "./tool-runtime.js";
import { registerToolDefinition } from "./define-tool.js";
import { routineToolDefinitions } from "./routines.js";
import { HevyOperationsService } from "../effect-services.js";

function register(
	client: HevyClient | null,
	operations?: HevyOperations,
	execution?: ToolExecutionContext,
) {
	const { server, registerTool: tool } = createMockMcpServer();
	const runtime = createToolRuntime({
		client,
		operations,
		execution,
		catalog: {} as never,
	});
	for (const definition of routineToolDefinitions)
		registerToolDefinition(server, runtime, definition);
	return tool;
}

function handler(tool: { mock: { calls: unknown[][] } }, name: string) {
	const call = tool.mock.calls.find(
		([registeredName]) => registeredName === name,
	);
	if (!call) throw new Error(`Tool ${name} was not registered`);
	return call.at(-1) as (args: JSONObject) => Promise<McpToolResponse>;
}

function registerRuntime(runtime: ReturnType<typeof createToolRuntime>) {
	const { server, registerTool: tool } = createMockMcpServer();
	for (const definition of routineToolDefinitions) {
		registerToolDefinition(server, runtime, definition);
	}
	return tool;
}

const routineInput = {
	routine: {
		title: "Push",
		folder_id: 3,
		exercises: [
			{
				exercise_template_id: "bench",
				superset_id: null,
				sets: [{ reps: 8, rep_range: { start: 8, end: 12 } }],
			},
		],
	},
};

describe("routine tools", () => {
	it("records expected telemetry for a missing routine", async () => {
		const client = createMockHevyClient();
		client.getRoutineById.mockRejectedValue(
			new HevyHttpError("routine not found", {
				status: 404,
				method: "GET",
				endpoint: "/v1/routines/:routineId",
			}),
		);
		const tool = register(client);
		const response = await handler(
			tool,
			"get-routine",
		)({
			routine_id: "missing",
		});

		expect(getResultTelemetry(response)).toMatchObject({
			itemCountBucket: "0",
			expected404Outcome: "not_found",
		});
	});

	it("maps pagination and identifiers to generated client calls", async () => {
		const client = createMockHevyClient();
		client.getRoutines.mockResolvedValue({ routines: [], page_count: 1 });
		client.getRoutineById.mockResolvedValue({
			routine: { id: "r1", title: "Push", folder_id: 3, exercises: [] },
		});
		const tool = register(client);
		await handler(tool, "get-routines")({ page: 2, page_size: 5 });
		await handler(tool, "get-routine")({ routine_id: "r1" });
		expect(client.getRoutines).toHaveBeenCalledWith({ page: 2, pageSize: 5 });
		expect(client.getRoutineById).toHaveBeenCalledWith("r1");
	});

	it("uses the injected routines list operation and execution context", async () => {
		const effect = vi.fn(() =>
			Effect.succeed({
				items: [{ id: "r1", title: "Push", exercises: [] }],
				page: 2,
				pageCount: 3,
			}),
		);
		const operations = {
			routines: {
				get: {
					descriptor: routinesGetDescriptor,
					effect: vi.fn(() => Effect.succeed({ routine: null })),
					execute: vi.fn(),
				},
				list: {
					descriptor: routinesListDescriptor,
					effect,
					execute: vi.fn(),
				},
			},
			workouts: {
				get: {
					descriptor: workoutsGetDescriptor,
					effect: vi.fn(() => Effect.succeed({ workout: null })),
					execute: vi.fn(),
				},
				list: {
					descriptor: workoutsListDescriptor,
					effect: vi.fn(() =>
						Effect.succeed({ items: [], page: 1, pageCount: 1 }),
					),
					execute: vi.fn(),
				},
			},
		} satisfies HevyOperations;
		const execution: ToolExecutionContext = {
			signal: new AbortController().signal,
			deadline: Date.now() + 5_000,
		};
		const tool = register(null, operations, execution);

		const response = await handler(
			tool,
			"get-routines",
		)({
			page: 2,
			page_size: 5,
		});

		expect(effect).toHaveBeenCalledWith({ page: 2, pageSize: 5 }, execution);
		expect(response).toMatchObject({
			structuredContent: {
				routines: [{ id: "r1", title: "Push" }],
				page: 2,
				page_count: 3,
			},
		});
	});

	it("uses the injected routines get operation and execution context", async () => {
		const effect = vi.fn(() =>
			Effect.succeed({
				routine: { id: "r1", title: "Push", exercises: [] },
			}),
