		)
		.mockReturnValueOnce(
			Effect.succeed({ items: [], page: 2, pageCount: undefined }),
		);
	const routinesGet = vi
		.fn()
		.mockReturnValueOnce(
			Effect.succeed({
				routine: null,
				expected404Outcome: "not_found" as const,
			}),
		)
		.mockReturnValueOnce(Effect.succeed({ routine: null }));
	const routinesList = vi
		.fn()
		.mockReturnValueOnce(
			Effect.succeed({
				items: [],
				page: 2,
