	) {
		const normalizedQuery = input.query?.toLowerCase();
		const limit = Math.min(
			Math.max(input.limit ?? DEFAULT_ROUTINE_SEARCH_LIMIT, 0),
			MAX_ROUTINE_SEARCH_LIMIT,
